public Matcher descend(String namespace, String name) {
    Matcher a = this.a.descend(namespace, name);
    Matcher b = this.b.descend(namespace, name);
    if (a == FAIL) {
        return b;
    } else if (b == FAIL) {
        return a;
    } else if (this.a == a && this.b == b) {
        return this;
    } else {
        return new CompositeMatcher(a, b);
    }
}
